	(1, 1, 'Entrega de uniformes escolares', 'El sistema de registro de notas ha sido actualizado. Les pedimos actualizar sus contraseñas para acceder al nuevo sistema.', 'alta', 0, NULL, 1, 1, '2025-11-08 15:44:13', '2025-11-08 15:44:13'),
